function render(id,push=true){if(!screens[id])return;if(push&&current!==id)history.push(current);current=id;app.innerHTML=screens[id]();document.querySelectorAll('[data-go]').forEach(el=>el.onclick=()=>render(el.dataset.go));document.querySelectorAll('[data-back]').forEach(el=>el.onclick=()=>render(history.pop()||'role',false));document.querySelectorAll('.screen-link').forEach(el=>el.classList.toggle('active',el.dataset.go===id));app.scrollTop=0}
function buildCatalog(){const box=$('#screen-list');box.innerHTML=Object.entries(groups).map(([g,ids])=>`<div class="group-title">${g} · ${ids.length} screens</div>${ids.map(id=>`<button class="screen-link" data-go="${id}">${labels[id]}</button>`).join('')}`).join('');document.querySelectorAll('[data-go]').forEach(el=>el.onclick=()=>render(el.dataset.go))}
buildCatalog();render('role',false);
